1|// Pure upload contract: limits, ids, strict parsing, word counts, part
2|// splitting, key builders, error codes. No env reads, no network, no
3|// secrets. Server modules in server/uploads/ build on it.
4|import type { RawSection } from "./clean-types";
5|import { FREE_BOOK_MAX_WORDS } from "./upload-policy";
6|
7|export { FREE_BOOK_MAX_WORDS };
8|
9|// BYOK books pay with the reader's key, so the ceiling is the 4 MB body.
10|export const BYOK_BOOK_MAX_WORDS = 400_000;
11|// Under the Hobby 4.5 MB request limit with JSON overhead to spare.
12|export const UPLOAD_MAX_BODY_BYTES = 4_000_000;
13|export const UPLOAD_STEP_BODY_BYTES = 4096;
14|export const UPLOAD_MAX_SECTIONS = 600;
15|export const UPLOAD_MAX_BLOCKS_PER_SECTION = 2000;
16|export const UPLOAD_MAX_BLOCK_CHARS = 20_000;
17|export const UPLOAD_MAX_TITLE_CHARS = 300;
18|export const UPLOAD_MAX_CHAPTERS = 500;
19|// One part fits one segment call plus its scenes inside the route budget.
20|export const UPLOAD_MAX_PART_PARAGRAPHS = 150;
21|// Global free-upload spend: USD 1 per UTC day, shared across readers.
22|export const UPLOAD_DAILY_SPEND_CAP_MICRO = 1_000_000;
23|// Ceiling on the per-book hold; the real cost reconciles at finalize.
24|export const UPLOAD_RESERVE_MICRO = 250_000;
25|export const UPLOAD_RESERVE_FLOOR_MICRO = 50_000;
26|export const UPLOAD_RESERVE_PER_PART_MICRO = 5_000;
27|
28|// Measured: a 3,955-word book cost USD 0.0027 (~0.7 micro/word). The hold
29|// prices 1 micro/word plus 5k micro/part for the judge and retries, so a
30|// 50k-word book holds ~110k micro, well under the USD 1/day cap.
31|export function uploadReserveMicro(parts: number, words: number): number {
32|  const sized = Math.max(UPLOAD_RESERVE_FLOOR_MICRO, parts * UPLOAD_RESERVE_PER_PART_MICRO + Math.max(0, Math.round(words)));
33|  return Math.min(UPLOAD_RESERVE_MICRO, sized);
34|}
35|export const UPLOAD_TTL_DAYS = 30;
36|export const UPLOAD_JOB_TTL_SEC = 30 * 24 * 3600;
37|export const UPLOAD_MODEL = "muse-spark-1.3-contributor";
38|export const UPLOAD_JEV_MODEL = "jev-1.14.0";
