131|// Strict parse at the trust boundary: exact fields only, defensive caps on
132|// every list and string, so a bad client cannot push unbounded work in.
133|export function parseUploadCreate(json: unknown): UploadCreateBody {
134|  if (!isRecord(json)) throw new UploadValidationError();
135|  const keys = Object.keys(json).sort().join(",");
136|  const base = "author,sections,title";
137|  if (keys !== base && keys !== "sections,title" && keys !== `${base},turnstileToken` && keys !== "sections,title,turnstileToken") {
138|    throw new UploadValidationError();
139|  }
140|  const title = json.title;
141|  if (typeof title !== "string" || title.trim().length === 0 || title.length > UPLOAD_MAX_TITLE_CHARS) {
142|    throw new UploadValidationError();
143|  }
144|  const author = json.author;
145|  if (author !== undefined && author !== null && (typeof author !== "string" || author.length > UPLOAD_MAX_TITLE_CHARS)) {
146|    throw new UploadValidationError();
147|  }
148|  const sections = json.sections;
149|  if (!Array.isArray(sections) || sections.length === 0 || sections.length > UPLOAD_MAX_SECTIONS) {
150|    throw new UploadValidationError();
151|  }
152|  const parsed: RawSection[] = sections.map((sec) => {
153|    if (!isRecord(sec)) throw new UploadValidationError();
154|    if (Object.keys(sec).sort().join(",") !== "blocks,docTitle,href,id,linear,navLabel,types") {
155|      throw new UploadValidationError();
156|    }
157|    if (typeof sec.id !== "string" || sec.id.length === 0 || sec.id.length > UPLOAD_MAX_TITLE_CHARS) {
158|      throw new UploadValidationError();
159|    }
160|    if (typeof sec.href !== "string" || sec.href.length > 2000) throw new UploadValidationError();
161|    if (typeof sec.linear !== "boolean") throw new UploadValidationError();
162|    if (!isStringArray(sec.types, 20, 100)) throw new UploadValidationError();
163|    for (const key of ["docTitle", "navLabel"] as const) {
164|      const value = sec[key];
165|      if (value !== null && (typeof value !== "string" || value.length > UPLOAD_MAX_TITLE_CHARS)) {
166|        throw new UploadValidationError();
167|      }
168|    }
169|    if (!Array.isArray(sec.blocks) || sec.blocks.length > UPLOAD_MAX_BLOCKS_PER_SECTION) {
170|      throw new UploadValidationError();
171|    }
172|    const blocks = sec.blocks.map((block) => {
173|      if (!isRecord(block)) throw new UploadValidationError();
174|      if (Object.keys(block).sort().join(",") !== "heading,text") throw new UploadValidationError();
175|      if (typeof block.text !== "string" || block.text.length > UPLOAD_MAX_BLOCK_CHARS) {
176|        throw new UploadValidationError();
177|      }
178|      if (typeof block.heading !== "boolean") throw new UploadValidationError();
179|      return { text: block.text, heading: block.heading };
180|    });
181|    return {
182|      id: sec.id,
183|      href: sec.href,
184|      linear: sec.linear,
185|      types: sec.types as string[],
186|      docTitle: sec.docTitle as string | null,
187|      navLabel: sec.navLabel as string | null,
188|      blocks,
189|    };
190|  });
191|  const out: UploadCreateBody = {
192|    title: title.trim(),
193|    author: typeof author === "string" && author.trim() !== "" ? author.trim() : null,
194|    sections: parsed,
195|  };
196|  if (json.turnstileToken !== undefined) {
197|    if (typeof json.turnstileToken !== "string" || json.turnstileToken.length > 2048) {
198|      throw new UploadValidationError();
199|    }
200|    out.turnstileToken = json.turnstileToken;
201|  }
202|  return out;
203|}
