225|export interface UploadPart {
226|  ch: number;
227|  part: number;
228|  startN: number;
229|  endN: number;
230|}
231|
232|export function partKey(part: Pick<UploadPart, "ch" | "part">): string {
233|  return `ch${part.ch}p${part.part}`;
234|}
235|
236|// Long chapters split into paragraph windows so one step stays in budget.
237|export function splitChapterParts(
238|  chapters: { ch: number; start_n: number; end_n: number }[],
239|  maxParas: number = UPLOAD_MAX_PART_PARAGRAPHS,
240|): UploadPart[] {
241|  const parts: UploadPart[] = [];
242|  for (const chapter of chapters) {
243|    let part = 1;
244|    for (let start = chapter.start_n; start <= chapter.end_n; start += maxParas, part += 1) {
245|      parts.push({ ch: chapter.ch, part, startN: start, endN: Math.min(start + maxParas - 1, chapter.end_n) });
246|    }
247|  }
248|  return parts;
249|}
250|
251|export function parseStepBody(json: unknown): { chapter?: number; turnstileToken?: string } {
252|  if (!isRecord(json)) throw new UploadValidationError();
253|  const keys = Object.keys(json).sort().join(",");
254|  if (keys !== "" && keys !== "chapter" && keys !== "turnstileToken" && keys !== "chapter,turnstileToken") {
255|    throw new UploadValidationError();
256|  }
257|  const out: { chapter?: number; turnstileToken?: string } = {};
258|  if (json.chapter !== undefined) {
259|    if (typeof json.chapter !== "number" || !Number.isSafeInteger(json.chapter) || json.chapter < 1) {
260|      throw new UploadValidationError();
261|    }
262|    out.chapter = json.chapter;
263|  }
264|  if (json.turnstileToken !== undefined) {
265|    if (typeof json.turnstileToken !== "string" || json.turnstileToken.length > 2048) {
266|      throw new UploadValidationError();
267|    }
268|    out.turnstileToken = json.turnstileToken;
269|  }
270|  return out;
271|}
