35|export function BookView({
36|  model,
37|  initialSceneId,
38|  panelsByChapter,
39|}: {
40|  model: ReaderModel;
41|  initialSceneId: string;
42|  panelsByChapter: { ch: number; panels: ChapterPanel[] }[];
43|}) {
44|  const [storedPref, setStoredPref] = useState<ImageStylePref | null>(null);
45|  // Server render uses the default so hydration matches; the live skin
46|  // applies on mount via useSyncExternalStore.
47|  const skin = useSkin();
48|  const pref = effectiveImageStylePref(storedPref, skin);
49|  const [currentId, setCurrentId] = useState(initialSceneId);
50|  const [panelsCh, setPanelsCh] = useState<number | null>(null);
51|  const readColRef = useRef<HTMLElement | null>(null);
52|  const figEls = useRef(new Map<string, HTMLElement>());
53|  const pic = usePictures({ bookId: model.bookId, textVersion: model.textVersion, sceneId: currentId, pref });
54|  const order = useMemo(() => model.chapters.flatMap((c) => c.scenes.map((s) => s.id)), [model]);
55|  const sceneOf = useMemo(() => {
56|    const map = new Map<string, { ch: number; k: number; n: number; chapterTitle: string }>();
57|    for (const chapter of model.chapters) {
58|      chapter.scenes.forEach((s, i) => {
59|        map.set(s.id, { ch: chapter.ch, k: i + 1, n: chapter.scenes.length, chapterTitle: chapter.title });
60|      });
61|    }
62|    return map;
63|  }, [model]);
64|  const panelsOf = useMemo(() => new Map(panelsByChapter.map((e) => [e.ch, e.panels])), [panelsByChapter]);
65|  const titles = useMemo(() => new Map(model.chapters.map((c) => [c.ch, c.title])), [model]);
66|  const info = sceneOf.get(currentId);
67|  // Spoiler reach: the highest chapter in view this visit. A chapter's
68|  // page and captions load only once the reader has reached it.
69|  const [maxReached, setMaxReached] = useState(() => sceneOf.get(initialSceneId)?.ch ?? 1);
70|  const maxReachedRef = useRef(maxReached);
71|  maxReachedRef.current = maxReached;
72|  const infoCh = info?.ch;
73|  useEffect(() => {
74|    if (infoCh !== undefined) setMaxReached((prev) => Math.max(prev, infoCh));
75|  }, [infoCh]);
76|  const bookIndex = order.indexOf(currentId);
77|  const lastChapter = model.chapters[model.chapters.length - 1]?.ch ?? 0;
78|
79|  // One commit path for every scene change: state, the live store the
80|  // music container reads, and the deep-link URL. No router pushes, so
81|  // scrolling never remounts.
82|  const commitScene = useCallback(
83|    (id: string) => {
84|      setCurrentId((prev) => (prev === id ? prev : id));
85|      setCurrentSceneId(id);
86|      window.history.replaceState(null, "", `/read/${model.bookId}/${id}`);
87|    },
88|    [model.bookId],
89|  );
90|
91|  // Land on the deep-linked scene with no animation, focus the column so
92|  // native keys scroll it, and pause narration follow on user input.
93|  useEffect(() => {
94|    const col = readColRef.current;
95|    if (!col) return;
96|    col.focus({ preventScroll: true });
97|    setCurrentSceneId(initialSceneId);
98|    scrollToSceneId(col, initialSceneId, false);
99|    return attachFollowPause(col);
100|  }, [initialSceneId]);
101|
102|  // The scene under the reading line (40% down the column) is current.
103|  // A thin rootMargin band, not ratios: a long scene filling the screen
104|  // must beat a short one fully in view, and the band fires exactly when
105|  // a section crosses the line. Ties keep document order. One observer,
106|  // no scroll listeners, no layout reads on scroll.
107|  useEffect(() => {
108|    const col = readColRef.current;
109|    if (!col) return;
110|    const seen = new Map<string, { id: string; ratio: number }>();
111|    const io = new IntersectionObserver(
112|      (entries) => {
113|        for (const entry of entries) {
114|          const id = (entry.target as HTMLElement).dataset.sceneId;
115|          if (!id) continue;
116|          if (entry.isIntersecting) seen.set(id, { id, ratio: entry.intersectionRatio });
117|          else seen.delete(id);
118|        }
119|        const next = pickCurrentScene(order, seen);
120|        if (!next) return;
121|        // Focus in a far chapter scrolls it under the reading line; that
122|        // scroll must not commit a later scene or push "reached" (and the
123|        // chat spoiler gate) forward.
124|        const active = document.activeElement;
125|        const focusCh = Number(
126|          active instanceof HTMLElement ? active.closest?.("[data-ch]")?.getAttribute("data-ch") : NaN,
127|        );
128|        if (
129|          Number.isFinite(focusCh) &&
130|          focusCh > maxReachedRef.current &&
131|          (sceneOf.get(next)?.ch ?? 0) > maxReachedRef.current
132|        )
133|          return;
134|        commitScene(next);
135|      },
136|      { root: col, rootMargin: "-40% 0px -59% 0px", threshold: 0 },
137|    );
138|    for (const section of col.querySelectorAll("[data-scene-id]")) io.observe(section);
139|    return () => io.disconnect();
140|  }, [order, commitScene, sceneOf]);
141|
142|  // Chapter jumps from outside the column arrive here.
143|  useEffect(() => {
144|    const onGoto = (event: Event) => gotoScene((event as CustomEvent<string>).detail);
145|    window.addEventListener(GOTO_SCENE_EVENT, onGoto);
