149|  useEffect(() => {
150|    setStoredPref(loadImageStylePref());
151|  }, []);
152|
153|  function changePref(next: ImageStylePref) {
154|    setStoredPref(next);
155|    saveImageStylePref(next);
156|  }
157|
158|  const closePanels = useCallback(() => setPanelsCh(null), []);
159|
160|  const figsByN = useMemo(() => groupFiguresByEndN(pic.figures), [pic.figures]);
161|
162|  function gotoFigure(fig: InlineFigure) {
163|    const el = figEls.current.get(fig.id) ?? null;
164|    const col = readColRef.current;
165|    if (col) noteUserScroll(col);
166|    el?.scrollIntoView({ block: "nearest" });
