1|import { buildReaderModel } from "@/core/reader";
2|import { loadBook } from "@/server/books";
3|import { loadNarrationEntries } from "@/server/narration";
4|import { Reader } from "../../reader";
5|
6|// Static shell: audio and music state persist across scene routes.
7|// Only slim metadata reaches the client: id, chapter, ordinal range,
8|// emotion. The chapter narration index (~1 MB) stays server-side; the
9|// client gets one small {chapter → src, manifest} map.
10|export default async function ReadBookLayout({
11|  children,
12|  params,
13|}: {
14|  children: React.ReactNode;
15|  params: Promise<{ bookId: string }>;
16|}) {
17|  const { bookId } = await params;
18|  const { book, scenes } = await loadBook(bookId);
19|  const model = buildReaderModel(book, { scenes });
20|  const slim = model.chapters.flatMap((chapter) =>
21|    chapter.scenes.map((scene) => {
22|      const paras = scene.paragraphs;
23|      return {
24|        id: scene.id,
25|        ch: chapter.ch,
26|        startN: paras[0]?.n ?? 0,
27|        endN: paras[paras.length - 1]?.n ?? 0,
28|        emotion: scene.emotion,
29|      };
30|    }),
31|  );
32|  const chapters = model.chapters.map((chapter) => ({
33|    ch: chapter.ch,
34|    title: chapter.title,
35|    firstSceneId: chapter.scenes[0]?.id ?? "",
36|  }));
37|  const narration = loadNarrationEntries(bookId);
38|  return (
39|    <Reader
40|      bookId={model.bookId}
41|      scenes={slim}
42|      chapters={chapters}
43|      bookTitle={model.title}
44|      bookAuthor={model.author}
45|      narration={narration}
46|    >
47|      {children}
48|    </Reader>
49|  );
50|}

