12|
13|export function StylePicker({ pref, onChange }: { pref: ImageStylePref; onChange: (pref: ImageStylePref) => void }) {
14|  const [custom, setCustom] = useState(pref.kind === "custom" ? pref.text : "");
15|  const [otherOpen, setOtherOpen] = useState(false);
16|  const customRef = useRef<HTMLInputElement | null>(null);
17|  const selected = resolveStyleSelect(pref, otherOpen);
18|  useEffect(() => {
19|    if (otherOpen) customRef.current?.focus();
20|  }, [otherOpen]);
21|  return (
22|    <div className="style-picker mtool">
23|      <span className="mtool-icon">
24|        <Icon name="brush" width={18} height={18} />
25|      </span>
26|      <div className="mtool-text">
27|        <label className="mtool-title" htmlFor="style-select">
28|          Picture style
29|        </label>
30|        <select
31|          id="style-select"
32|          className="mtool-sub"
33|          value={selected}
34|          onChange={(e) => {
35|            const next = e.target.value;
36|            if (next === STYLE_OTHER_VALUE) {
37|              setCustom(pref.kind === "custom" ? pref.text : "");
38|              setOtherOpen(true);
39|              return;
40|            }
41|            setOtherOpen(false);
42|            onChange({ kind: "preset", id: next });
43|          }}
44|          onKeyDown={(e) => {
45|            if (e.key === "Escape") setOtherOpen(false);
46|          }}
47|        >
48|          {STYLE_PRESETS.map((p) => (
49|            <option key={p.id} value={p.id}>
50|              {p.label}
51|            </option>
52|          ))}
53|          <option value={STYLE_OTHER_VALUE}>Other…</option>
54|        </select>
55|        {selected === STYLE_OTHER_VALUE ? (
56|          <div className="style-custom">
57|            <input
58|              ref={customRef}
59|              type="text"
60|              value={custom}
61|              maxLength={60}
62|              placeholder="e.g. Japanese woodblock"
