2|import type { ImageErrorCode, ImageResponse } from "@/core/images";
3|
4|const POLL_MS = 3000;
5|const POLL_MAX = 40;
6|
7|async function postImage(body: unknown): Promise<ImageResponse> {
8|  // One generating request runs up to the 120 s server budget, so this
9|  // outlasts it; a timeout surfaces as the friendly retry state below.
10|  const res = await fetch("/api/images", {
11|    method: "POST",
12|    headers: { "Content-Type": "application/json" },
13|    body: JSON.stringify(body),
14|    signal: AbortSignal.timeout(130_000),
15|  });
16|  return (await res.json()) as ImageResponse;
17|}
18|
19|// Shared by the chapter page hook: one poll loop for every picture kind.
20|// Thrown when the API needs a human proof; the caller surfaces the
21|// widget once instead of polling through the failure.
22|export class HumanNeeded extends Error {
23|  constructor() {
24|    super(MSG_HUMAN);
25|    this.name = "HumanNeeded";
26|  }
27|}
28|
29|// Carries the API error code past poll, so quota and budget failures can
30|// hide their retry button. The message stays the server's friendly copy.
31|export class ImageRequestError extends Error {
32|  code: ImageErrorCode;
33|  constructor(code: ImageErrorCode, message: string) {
34|    super(message);
35|    this.name = "ImageRequestError";
36|    this.code = code;
37|  }
38|}
39|
40|export function isQuotaCode(code: ImageErrorCode): boolean {
41|  return code === "quota" || code === "budget" || code === "daily_budget";
42|}
43|
44|export async function poll(
45|  body: Record<string, unknown>,
46|  token?: string,
47|): Promise<{ url: string; caption: string }> {
48|  let left = POLL_MAX;
49|  let first = true;
50|  for (;;) {
51|    let res: ImageResponse;
52|    try {
53|      // The token rides the first post only; later polls reuse the cookie.
54|      const payload = first && token ? { ...body, turnstileToken: token } : body;
55|      first = false;
56|      res = await postImage(payload);
57|    } catch {
58|      throw new Error(MSG_FAILED);
59|    }
60|    if (res.status === "ready") return { url: res.url, caption: res.caption };
61|    if (res.status === "error") {
62|      if (res.code === "human") throw new HumanNeeded();
63|      throw new ImageRequestError(res.code, res.message);
64|    }
65|    left -= 1;
66|    if (left <= 0) throw new Error(MSG_RETRY);
67|    await new Promise((done) => setTimeout(done, POLL_MS));
68|  }
